import { ChatroomEventInterface, ChatroomInitializeOptions } from 'nim-web-sdk-ng/dist/CHATROOM_BROWSER_SDK/ChatroomInterface';
import { ArgumentMap } from 'eventemitter3';
import { ChatroomMessage, ISendTipMsgOptions, ChatroomMember, IBaseSendFileOptions } from 'nim-web-sdk-ng/dist/CHATROOM_BROWSER_SDK/types';
import { QueryMembersOptions, UpdateMyRoomRoleOptions } from 'nim-web-sdk-ng/dist/CHATROOM_BROWSER_SDK/ChatroomMemberServiceInterface';
import { QueryMessageHistoryOptions } from 'nim-web-sdk-ng/dist/CHATROOM_BROWSER_SDK/ChatroomMsgServiceInterface';
export interface ChatroomOptions extends ChatroomInitializeOptions {
    callbackOptions?: {
        [key: string]: (...args: any) => void;
    };
}
export type IM1ChatroomMsgStatus = 'success' | 'fail' | 'sending';
export interface IChatroomKitCore {
    version: string;
    getChatroom(): any;
    /**
     * 建立连接，并且登录
     */
    connect(): Promise<void>;
    /**
     * 断开连接
     * 退出登录状态，并断开 websocket 连接
     * disconnect完成后，实例不会被销毁，可再次 connect 方法登录IM
     */
    disconnect(): Promise<void>;
    /**
     * 更新初始化传入的参数，在初始化完成后使用
     *
     * 请注意！传入的参数会在下一次调用connect或重连生效
     *
     */
    setOptions(options: ChatroomInitializeOptions): void;
    /**
     * 销毁实例
     * 销毁当前 IM 实例，同时会退出登录状态，并断开websocket连接
     * 移除所有监听事件，销毁部分内部变量，并且此实例再也无法调用 connect 恢复 IM 连接
     */
    destroy(): Promise<void>;
    /**
     * 发送文本消息
     * @param options
     */
    sendTextMsg(options: ISendTipMsgOptions): Promise<ChatroomMessage>;
    /**
     * 发送文件消息
     * @param options
     */
    sendFileMsg(options: IBaseSendFileOptions): Promise<ChatroomMessage>;
    /**
     * 查询聊天室成员
     * @param options
     */
    queryMembers(options: QueryMembersOptions): Promise<ChatroomMember[]>;
    /**
     * 更新自己在聊天室中的信息
     * @param options
     */
    updateMyRoomRole(options: UpdateMyRoomRoleOptions): Promise<void>;
    /**
     * 查询历史消息
     * @param options
     */
    queryMessageHistory(options: QueryMessageHistoryOptions): Promise<ChatroomMessage[]>;
    on<T extends keyof ChatroomEventInterface>(eventName: T, fn: (...args: ArgumentMap<ChatroomEventInterface>[Extract<T, keyof ChatroomEventInterface>]) => void, context?: any): this;
    off<T extends keyof ChatroomEventInterface>(eventName: T, fn?: ((...args: ArgumentMap<ChatroomEventInterface>[Extract<T, keyof ChatroomEventInterface>]) => void) | undefined, context?: any, once?: boolean | undefined): this;
    emit<T extends keyof ChatroomEventInterface>(event: T, ...args: ArgumentMap<ChatroomEventInterface>[Extract<T, keyof ChatroomEventInterface>]): boolean;
}
